<script setup lang="ts">definePageMeta({middleware:'auth'});useHead({title:'سبد خرید'});const{cart,load,update,remove}=useCart(),{media}=useShopApi();await load();const money=(v=0)=>new Intl.NumberFormat('fa-IR').format(v)</script>
<template><div class="mx-auto max-w-7xl px-4 py-10"><h1 class="text-2xl font-black">سبد خرید شما</h1><div v-if="cart.items.length" class="mt-7 grid gap-7 lg:grid-cols-[1fr_340px]"><section class="space-y-3"><article v-for="item in cart.items" :key="item.id" class="flex gap-4 rounded-2xl border bg-white p-4"><div class="size-28 shrink-0 overflow-hidden rounded-xl bg-stone-100"><img v-if="item.variant.product.media?.[0]" :src="media(item.variant.product.media[0].path)" class="size-full object-cover"></div><div class="flex flex-1 flex-col justify-between"><div><h2 class="font-black">{{item.variant.product.title}}</h2><p class="mt-2 text-xs text-slate-400">{{Object.values(item.variant.attributes||{}).filter(Boolean).join(' / ')}}</p></div><div class="flex items-end justify-between"><div class="flex items-center rounded-xl border"><button class="size-9" @click="item.quantity===1?remove(item.id):update(item.id,item.quantity-1)">−</button><span class="w-8 text-center font-bold">{{item.quantity}}</span><button class="size-9" @click="update(item.id,item.quantity+1)">＋</button></div><p class="font-black text-brand-900">{{money(item.variant.price*item.quantity)}} تومان</p></div></div></article></section><aside class="h-fit rounded-2xl border bg-white p-5 shadow-soft"><div class="flex justify-between text-sm text-slate-500"><span>جمع کالاها</span><span>{{money(cart.subtotal)}} تومان</span></div><p class="mt-4 text-xs leading-6 text-slate-400">هزینه ارسال در مرحله بعد و بر اساس روش تحویل محاسبه می‌شود.</p><div class="my-5 border-t"></div><div class="flex justify-between font-black"><span>مبلغ سبد</span><span>{{money(cart.subtotal)}} تومان</span></div><NuxtLink to="/checkout" class="mt-5 block rounded-xl bg-brand-700 py-4 text-center font-black text-white">ادامه فرایند خرید</NuxtLink></aside></div><div v-else class="mt-8 rounded-3xl border border-dashed bg-white p-16 text-center"><p class="text-xl font-black">سبد خرید خالی است</p><p class="mt-2 text-sm text-slate-400">محصولی را انتخاب کنید تا اینجا نمایش داده شود.</p><NuxtLink to="/products" class="mt-6 inline-block rounded-xl bg-brand-700 px-6 py-3 font-bold text-white">مشاهده محصولات</NuxtLink></div></div></template>
